import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int totalWords = sc.nextInt();
        sc.nextLine();
        String inputLine = sc.nextLine();

        StringBuilder resultLine = new StringBuilder();
        int countWordsInParentheses = 0;
        int position = 0;

        while (position < inputLine.length()) {
            if (inputLine.charAt(position) == '(') {
                resultLine.append('_');
                position++;
                StringBuilder inside = new StringBuilder();
                while (inputLine.charAt(position) != ')') {
                    inside.append(inputLine.charAt(position));
                    position++;
                }
                String[] wordsInside = inside.toString().split("_");
                for (String w : wordsInside) {
                    if (!w.isEmpty()) {
                        countWordsInParentheses++;
                    }
                }
            } else {
                resultLine.append(inputLine.charAt(position));
            }
            position++;
        }

        String[] segments = resultLine.toString().split("_");
        int maxLength = 0;
        for (String segment : segments) {
            if (!segment.isEmpty() && segment.length() > maxLength) {
                maxLength = segment.length();
            }
        }

        System.out.println(maxLength + " " + countWordsInParentheses);
        sc.close();
    }
}
