int main() {
    int totalWords;
    std::cin >> totalWords;
    std::cin.ignore(); // ignore the newline after the integer input
    std::string inputLine;
    std::getline(std::cin, inputLine);

    std::string resultLine;
    int countWordsInParentheses = 0;
    size_t position = 0;

    while (position < inputLine.length()) {
        if (inputLine[position] == '(') {
            resultLine += '_';
            position++;
            std::string inside;
            while (position < inputLine.length() && inputLine[position] != ')') {
                inside += inputLine[position];
                position++;
            }
            // Skip the closing parenthesis
            if (position < inputLine.length() && inputLine[position] == ')') {
                position++;
            }
            // Split inside string by '_'
            std::stringstream ss(inside);
            std::string word;
            while (std::getline(ss, word, '_')) {
                if (!word.empty()) {
                    countWordsInParentheses++;
                }
            }
        } else {
            resultLine += inputLine[position];
            position++;
        }
    }

    // Split resultLine by '_'
    std::stringstream ss(resultLine);
    std::string segment;
    int maxLength = 0;
    while (std::getline(ss, segment, '_')) {
        if (!segment.empty() && static_cast<int>(segment.length()) > maxLength) {
            maxLength = segment.length();
        }
    }

    std::cout << maxLength << " " << countWordsInParentheses << std::endl;
    return 0;
}
